    id: "cc51",
    domain: "cloud-concepts",
    text: "A CFO is comparing the total cost of ownership (TCO) of running an application on-premises versus on AWS. Which TWO cost components are typically included in the on-premises estimate but are eliminated or significantly reduced when moving to AWS?",
    options: [
      { id: "a", text: "Data center facilities costs such as power, cooling, and physical space" },
      { id: "b", text: "Application licensing for software that the company brings to AWS" },
      { id: "c", text: "Hardware procurement and refresh cycles for servers and storage" },
      { id: "d", text: "Salaries of developers who build the application" },
      { id: "e", text: "Third-party SaaS subscriptions used by the business" },
      { id: "f", text: "Compute usage charges for the application's servers" },
      { id: "g", text: "Network bandwidth charges from the internet service provider" },
      { id: "h", text: "Cost of end-user laptops and workstations" },
      { id: "i", text: "Staff time spent racking, cabling, and repairing physical equipment" },
      { id: "j", text: "Excess capacity purchased in advance to handle peak demand" },
    ],
    correctOptionIds: ["a", "c", "i", "j"],
    answerType: "multi",
    explanation: "A TCO analysis covers direct costs such as servers, storage, and networking hardware plus indirect costs such as facilities, power, cooling, and the labor required to operate them. Moving to AWS removes hardware procurement and refresh, physical facilities, and hands-on hardware labor, and elasticity avoids paying for idle peak capacity.",
    optionRationale: {
      a: "Power, cooling, rack space, and physical security are facilities costs that AWS absorbs into its service pricing, so they disappear from the customer's estimate.",
      b: "Software licenses that the company brings to AWS (BYOL) are still paid by the company; they do not disappear with migration.",
      c: "AWS owns and refreshes the physical servers and storage, so the customer no longer buys hardware or budgets for periodic replacement.",
      d: "Developer salaries are an application cost that remains the same regardless of where the application runs.",
      e: "SaaS subscriptions are paid regardless of where the company's own infrastructure runs.",
      f: "Compute charges are an AWS cost that appears in the cloud estimate, not one eliminated by moving.",
      g: "Internet connectivity is still needed on AWS, and data transfer out is billed by AWS.",
      h: "End-user devices are unrelated to where the application is hosted.",
      i: "AWS performs the hands-on hardware work, so the labor of installing and repairing physical equipment drops out of the customer's estimate.",
      j: "On-premises estimates include hardware sized for peak load that sits idle most of the time, while on AWS capacity scales with actual demand.",
    },
    referenceUrl: "https://aws.amazon.com/economics/",
    referenceLabel: "AWS Cloud Economics Center",
