      g: "Multi-AZ replicates within one RDS deployment; it cannot migrate from an on-premises Oracle database.",
      h: "Glue is an ETL service for analytics pipelines, not a tool for schema conversion and low-downtime cutover.",
      i: "DMS Schema Conversion, the managed console version of schema conversion, converts Oracle schemas and code for Aurora PostgreSQL while DMS keeps the databases in sync.",
