    id: "cc64",
    domain: "cloud-concepts",
    text: "A retailer's IT team historically ordered servers nine months before a product launch, guessing at peak demand. Launches either wasted money on idle hardware or crashed under unexpected traffic. Which advantage of cloud computing directly addresses this problem?",
    options: [
      { id: "a", text: "Benefit from massive economies of scale" },
      { id: "b", text: "Stop guessing capacity" },
      { id: "c", text: "Go global in minutes" },
      { id: "d", text: "Stop spending money running and maintaining data centers" },
      { id: "e", text: "Increase speed and agility" },
      { id: "f", text: "Trade fixed expense for variable expense" },
      { id: "g", text: "Achieve fault tolerance across Regions" },
      { id: "h", text: "Eliminate the need for load testing" },
      { id: "i", text: "Scale capacity up or down as traffic changes" },
    ],
    correctOptionIds: ["b", "i"],
    answerType: "single",
    explanation: "'Stop guessing capacity' is one of the six advantages of cloud computing: you can provision as much or as little as you need and scale up or down within minutes instead of forecasting demand months ahead.",
    optionRationale: {
      a: "Economies of scale lower unit prices because AWS aggregates usage from many customers; it doesn't solve the capacity forecasting problem.",
      b: "Elastic provisioning lets the retailer match capacity to actual demand, removing the need to guess nine months in advance.",
      c: "Going global in minutes is about deploying to multiple Regions quickly, not about sizing capacity.",
      d: "Eliminating data center operations is a benefit, but the specific problem described is capacity forecasting.",
      e: "Agility describes provisioning resources quickly; the scenario is specifically about guessing capacity ahead of demand.",
      f: "This benefit is about how spending is accounted for, not about avoiding capacity forecasts.",
      g: "Fault tolerance is an architectural property, not one of the six advantages of cloud computing.",
      h: "Cloud computing does not remove the need to test how applications behave under load.",
      i: "Scaling capacity with actual traffic lets the retailer provision for real demand at each launch instead of forecasting it nine months ahead.",
    },
    referenceUrl: "https://docs.aws.amazon.com/whitepapers/latest/aws-overview/six-advantages-of-cloud-computing.html",
    referenceLabel: "Six Advantages of Cloud Computing",
    consoleUrl: "https://console.aws.amazon.com/ec2/home#AutoScalingGroups:",
    consoleLabel: "EC2 > Auto Scaling Groups",
    diagram: "flowchart LR\n  Old[Forecast 9 months ahead] --> Waste[Idle servers or outages]\n  Cloud[Provision on demand] --> Match[Capacity matches real traffic]\n  Match --> Scale[Scale up or down in minutes]",
