    correctOptionIds: ["b", "i"],
    answerType: "single",
    explanation: "Each AWS Region is a separate geographic area and AWS does not move or replicate customer content outside the Region the customer selects, except as the customer configures (for example, cross-Region replication) or as legally required.",
