      b: "Customers choose the Region, and their content remains there unless they enable cross-Region features themselves.",
      c: "There is no automatic continental replication and no opt-out requirement; the customer controls any cross-Region movement.",
      d: "AWS maintenance does not involve moving customer data between Regions.",
      e: "AWS does not replicate customer data to other Regions, inside or outside the EU, unless the customer configures it.",
      f: "No customer data is copied to us-east-1 automatically.",
      g: "AWS does not relocate customer data based on capacity.",
      h: "Having resources in multiple Regions does not cause automatic data replication between them.",
