    id: "cc86",
    domain: "cloud-concepts",
    text: "A solutions architect is explaining why deploying across multiple Availability Zones improves resilience. Which TWO statements about Availability Zones are correct?",
    options: [
      { id: "a", text: "Availability Zones within a Region are physically separated by a meaningful distance to reduce the chance of a shared failure" },
      { id: "b", text: "Availability Zones in the same Region are connected by low-latency, high-bandwidth private links" },
      { id: "c", text: "Every Availability Zone is located in a different country from the others in its Region" },
      { id: "d", text: "Data is automatically replicated between Availability Zones for every AWS service by default" },
      { id: "e", text: "An Availability Zone always consists of exactly one data center" },
      { id: "f", text: "Availability Zones in a Region share a single power grid feed and cooling plant to simplify operations" },
      { id: "g", text: "Traffic between Availability Zones in the same Region must traverse the public internet" },
      { id: "h", text: "Each AWS Region contains exactly two Availability Zones" },
      { id: "i", text: "All Availability Zones in a Region are within about 100 km of each other" },
      { id: "j", text: "Network traffic flowing between Availability Zones is encrypted" },
    ],
    correctOptionIds: ["a", "b", "i", "j"],
    answerType: "multi",
    explanation: "AZs are one or more discrete data centers with independent power, cooling, and networking, separated by many kilometers but within about 100 km so that synchronous replication is possible over low-latency, encrypted private links.",
    optionRationale: {
      a: "Physical separation isolates AZs from localized events such as fires, floods, or power failures.",
      b: "Low-latency links between AZs enable synchronous replication and multi-AZ architectures.",
      c: "All AZs in a Region are in the same geographic area (and country); a Region defines that area.",
      d: "Replication across AZs depends on the service and configuration; for example EC2 instance storage is not replicated.",
      e: "An AZ can contain multiple data centers, which is why it is described as one or more discrete data centers.",
      f: "Each AZ has independent power, cooling, and networking precisely so that a shared utility failure does not take down more than one AZ.",
      g: "AZs in a Region are connected by private, redundant metro fiber; inter-AZ traffic never leaves the AWS network.",
      h: "Regions have three or more AZs, and many have more; only newer accounts in US West (N. California) are limited to two of its AZs.",
      i: "AWS keeps the AZs of a Region within roughly 100 km so they are far enough apart for isolation yet close enough for synchronous replication.",
      j: "AWS encrypts all traffic between Availability Zones as it crosses the links between its facilities.",
    },
    referenceUrl: "https://docs.aws.amazon.com/whitepapers/latest/aws-fault-isolation-boundaries/availability-zones.html",
    referenceLabel: "AWS Fault Isolation Boundaries – Availability Zones",
    consoleUrl: "https://console.aws.amazon.com/ec2/home#Settings:tab=zones",
    consoleLabel: "EC2 > Settings > Zones",
    diagram: "flowchart LR\n  R[Region us-east-1] --> A[AZ a - one or more data centers]\n  R --> B[AZ b - one or more data centers]\n  R --> C[AZ c - one or more data centers]\n  A -->|low-latency private links| B\n  B -->|low-latency private links| C",
