      f: "AWS Transfer Family provides managed SFTP, FTPS, FTP, and AS2 endpoints into S3 for partners; it does not pull files from an on-premises NFS server on a schedule.",
      g: "S3 Transfer Acceleration speeds up uploads over the public internet via edge locations; it is not an NFS migration service and is unnecessary over Direct Connect.",
      h: "AWS Snowmobile is a retired exabyte-scale physical truck offering, and the requirement rules out shipping hardware.",
      i: "DataSync reads from the NFS share through an agent deployed on premises and moves the files to S3 over Direct Connect with scheduling, encryption, and integrity checks.",
