    id: "cc96",
    domain: "cloud-concepts",
    text: "A compliance officer asks who is responsible for guarding the physical data centers, controlling badge access, and decommissioning failed storage disks that hold customer data when a company runs its application on AWS. Under the shared responsibility model, whose responsibility is this?",
    options: [
      { id: "a", text: "AWS, as part of security of the cloud" },
      { id: "b", text: "The customer, as part of security in the cloud" },
      { id: "c", text: "Shared equally between AWS and the customer" },
      { id: "d", text: "A third-party auditor selected by the customer" },
      { id: "e", text: "The customer, but only when using Dedicated Hosts" },
      { id: "f", text: "The AWS Partner Network consulting partner that built the application" },
      { id: "g", text: "AWS, but only for customers with an Enterprise Support plan" },
      { id: "h", text: "The customer, because the disks hold the customer's data" },
      { id: "i", text: "AWS, as a control the customer fully inherits" },
    ],
    correctOptionIds: ["a", "i"],
    answerType: "single",
    explanation: "AWS is responsible for security of the cloud, including the physical security of facilities, hardware, and the secure decommissioning of storage media; these are inherited controls that customers rely on without operating them. Customers are responsible for security in the cloud, such as their data, identities, and configurations.",
    optionRationale: {
      a: "Facilities, hardware, and media disposal are part of the global infrastructure that AWS protects.",
      b: "Customers never gain physical access to AWS data centers, so physical controls cannot be their responsibility.",
      c: "Physical infrastructure is wholly AWS's responsibility, not a shared control.",
      d: "Auditors verify controls; they do not operate them.",
      e: "Dedicated Hosts give the customer a dedicated physical server, but AWS still owns and secures the facility and decommissions the hardware.",
      f: "A consulting partner may build the workload, but physical data center security is always AWS's responsibility.",
      g: "Physical security and media decommissioning are part of security of the cloud for every customer regardless of support plan.",
      h: "Customers own their data, but the physical media and its secure destruction are AWS's responsibility under security of the cloud.",
      i: "Physical and environmental controls are inherited controls: AWS operates them and customers inherit them without taking any action.",
    },
    referenceUrl: "https://aws.amazon.com/compliance/shared-responsibility-model/",
    referenceLabel: "AWS Shared Responsibility Model",
    consoleUrl: "https://console.aws.amazon.com/artifact/reports",
    consoleLabel: "AWS Artifact > Reports",
    diagram: "flowchart TB\n  AWS[AWS responsibility] --> Phys[Physical data center security]\n  AWS --> HW[Hardware and media disposal]\n  Cust[Customer responsibility] --> Data[Customer data]\n  Cust --> IAM[Identity and access management]",
