    consoleLabel: "Amazon S3 > Buckets > Management > Lifecycle rules",
    diagram: "flowchart LR\n  Std[S3 Standard] -->|90 days| IA[S3 Standard-IA]\n  IA -->|365 days| Deep[S3 Glacier Deep Archive]\n  Deep -->|expire unneeded| Del[Delete]",
