    id: "cc137",
    domain: "cloud-concepts",
    text: "During portfolio assessment, a company assigns one of the 7 R migration strategies to each of its 300 applications. Which TWO strategies result in an application NOT being moved to AWS at all? (Select TWO.)",
    options: [
      { id: "a", text: "Retire" },
      { id: "b", text: "Retain" },
      { id: "c", text: "Rehost" },
      { id: "d", text: "Relocate" },
      { id: "e", text: "Replatform" },
      { id: "f", text: "Repurchase" },
      { id: "g", text: "Refactor" },
      { id: "h", text: "Re-architect for containers" },
      { id: "i", text: "Retire (decommission)" },
      { id: "j", text: "Retain (revisit later)" },
    ],
    correctOptionIds: ["a", "b", "i", "j"],
    answerType: "multi",
    explanation: "Retire means decommissioning an application that is no longer needed, and Retain means deliberately leaving it in its current environment for now. Every other R (rehost, relocate, replatform, repurchase, refactor) moves the workload or its function to AWS or to a cloud-based replacement.",
    optionRationale: {
      a: "A retired application is switched off and removed, so there is nothing to migrate.",
      b: "A retained application stays on-premises, typically because of dependencies, recent upgrades, or plans to revisit it later.",
      c: "Rehost lifts and shifts the application onto AWS unchanged.",
      d: "Relocate moves VMware or container workloads to AWS without changing them.",
      e: "Replatform moves the application to AWS with limited optimizations such as adopting a managed database.",
      f: "Repurchase replaces the application with a cloud-based SaaS product, so its function moves to the cloud.",
      g: "Refactor rewrites the application to be cloud-native on AWS.",
      h: "Re-architecting for containers is a form of refactoring and still moves the application onto AWS.",
      i: "Retiring an application means decommissioning it because it is no longer needed, so it is never moved to AWS.",
      j: "Retaining an application means leaving it where it runs today and revisiting the decision later, so it is not moved to AWS.",
    },
    referenceUrl: "https://docs.aws.amazon.com/prescriptive-guidance/latest/large-migration-guide/migration-strategies.html",
    referenceLabel: "Large Migration Guide - Migration Strategies",
