    id: "cc144",
    domain: "cloud-concepts",
    text: "A development team currently merges code weekly and deploys manually once a month. A consultant recommends adopting continuous integration and continuous delivery. Which statement correctly describes the difference between the two practices?",
    options: [
      { id: "a", text: "Continuous integration automatically builds and tests every code change when it is merged; continuous delivery extends this so every change that passes is automatically prepared for release to production" },
      { id: "b", text: "Continuous integration is the practice of deploying to production several times a day; continuous delivery is a manual code review process" },
      { id: "c", text: "Continuous integration and continuous delivery are AWS services that replace version control" },
      { id: "d", text: "Continuous delivery removes the need for automated testing because AWS validates the code" },
      { id: "e", text: "Continuous integration means running every build on a dedicated on-premises server; continuous delivery means running builds in the cloud" },
      { id: "f", text: "Continuous integration merges code once per release cycle; continuous delivery merges code after every commit" },
      { id: "g", text: "Continuous delivery always pushes every passing change to production with no manual approval, while continuous integration requires an approval gate" },
      { id: "h", text: "Continuous integration is provided by AWS CodeDeploy and continuous delivery by AWS CodeBuild" },
      { id: "i", text: "CI merges and automatically tests changes many times a day; CD keeps every tested build ready to release at any time" },
    ],
    correctOptionIds: ["a", "i"],
    answerType: "single",
    explanation: "Continuous integration (CI) means developers frequently merge changes into a shared repository, where each change is automatically built and tested. Continuous delivery (CD) builds on CI by automatically packaging and staging every successful change so it is always ready to be released, with a final manual or automatic approval. Continuous deployment goes one step further and pushes every passing change to production with no manual gate. On AWS these practices are implemented with services such as CodeBuild, CodeDeploy, and CodePipeline.",
    optionRationale: {
      a: "Correct. CI is about frequent, automatically tested merges; CD keeps a deployable artifact ready at all times.",
      b: "Deploying to production automatically for every change is continuous deployment, and code review is not what continuous delivery means.",
      c: "They are engineering practices, and they rely on version control rather than replacing it.",
      d: "Automated testing is central to both practices; AWS does not validate application logic for you.",
      e: "CI and CD are practices independent of where build servers run.",
      f: "CI is about merging frequently, typically many times a day, not once per release cycle.",
      g: "Pushing every passing change to production automatically is continuous deployment; continuous delivery keeps a final release decision, and CI has no approval gate concept.",
      h: "CodeBuild is the build service used for CI, and CodeDeploy handles deployment; the services are reversed.",
      i: "Correct. CI centers on frequent, automatically built and tested merges, and CD extends it so each passing build is staged and releasable.",
    },
    referenceUrl: "https://docs.aws.amazon.com/whitepapers/latest/practicing-continuous-integration-continuous-delivery/welcome.html",
    referenceLabel: "Practicing Continuous Integration and Continuous Delivery on AWS",
