    explanation: "AWS Outposts extends AWS infrastructure into a customer facility, so the shared responsibility model shifts slightly. AWS owns, installs, monitors, patches, and repairs the Outposts equipment, just as it does in its own Regions. Because the rack sits in the customer's building, the customer is responsible for the physical security of the facility, reliable power and cooling, and the network link back to the parent AWS Region, in addition to its usual responsibilities for data, identities, and operating systems.",
