      c: "AWS ships replacement components and performs the hardware maintenance.",
      d: "AWS monitors the Outposts infrastructure and its service link.",
      e: "AWS delivers and installs the Outposts rack and validates its connection to the Region.",
      f: "AWS operates the hypervisor and virtualization layer on Outposts just as it does in its own Regions.",
