    correctOptionIds: ["a", "i"],
    answerType: "single",
    explanation: "The Sustainability pillar applies the shared responsibility model: AWS is responsible for sustainability of the cloud, meaning power and water efficiency, renewable energy procurement, and hardware utilization in its global infrastructure. Customers are responsible for sustainability in the cloud, which includes choosing efficient Regions, right-sizing, scaling down idle resources, using managed and serverless services, and deleting data that is no longer needed.",
    optionRationale: {
      a: "Correct. The split mirrors the security model: 'of the cloud' is AWS, 'in the cloud' is the customer.",
      b: "How efficiently a workload uses cloud resources is in the customer's control.",
      c: "Data center efficiency and energy sourcing are controlled by AWS.",
      d: "Sustainability is a Well-Architected pillar and explicitly uses the shared responsibility model.",
      e: "The roles are reversed; customers right-size their own resources and AWS procures renewable energy for its infrastructure.",
      f: "Support plans affect access to AWS Support; they do not change the shared responsibility model.",
      g: "Partners may help customers, but responsibility for sustainability of and in the cloud remains with AWS and the customer respectively.",
      h: "The roles are reversed; AWS manages data center efficiency and customers manage their own data lifecycle.",
      i: "Correct. Efficiency of the underlying infrastructure is AWS's sustainability of the cloud, and efficient use of provisioned resources is the customer's sustainability in the cloud.",
    },
    referenceUrl: "https://docs.aws.amazon.com/wellarchitected/latest/sustainability-pillar/the-shared-responsibility-model.html",
    referenceLabel: "Shared responsibility model - Sustainability Pillar",
