    id: "cc150",
    domain: "cloud-concepts",
    text: "A solutions architect explains that Amazon CloudFront has more than one layer of infrastructure between the viewer and the origin. Which statement correctly describes Regional edge caches?",
    options: [
      { id: "a", text: "Regional edge caches sit between edge locations and the origin, holding a larger cache so that objects evicted from an edge location can still be served without going back to the origin" },
      { id: "b", text: "Regional edge caches are the same as AWS Regions and host EC2 instances" },
      { id: "c", text: "Regional edge caches store data permanently as a replacement for Amazon S3" },
      { id: "d", text: "Regional edge caches are only used for DNS resolution by Route 53" },
      { id: "e", text: "Regional edge caches are where Lambda@Edge functions must be deployed before they can run at edge locations" },
      { id: "f", text: "Regional edge caches are used only for dynamic content and never cache static objects" },
      { id: "g", text: "Regional edge caches are optional and must be enabled per distribution for an additional hourly fee" },
      { id: "h", text: "Regional edge caches are AWS Local Zones repurposed to serve CloudFront traffic" },
      { id: "i", text: "Regional edge caches are fewer than edge locations, but each has a larger cache" },
    ],
    correctOptionIds: ["a", "i"],
    answerType: "single",
    explanation: "CloudFront's global infrastructure has hundreds of edge locations (points of presence) close to viewers plus a smaller number of Regional edge caches. When an object is not in an edge location's cache, CloudFront checks the nearest Regional edge cache, which has a larger cache and holds objects longer, before fetching from the origin. This improves cache hit ratios and reduces load on origins.",
    optionRationale: {
      a: "Correct. Regional edge caches are a mid-tier cache with more capacity, reducing origin fetches for less popular content.",
      b: "Regional edge caches are part of the CloudFront network; they are not AWS Regions and do not run customer EC2 instances.",
      c: "They are caches, not durable storage; the origin remains the source of truth.",
      d: "DNS resolution is handled by Route 53 edge infrastructure, not by Regional edge caches.",
      e: "Lambda@Edge functions are deployed from us-east-1 and replicated to edge locations; Regional edge caches are not a deployment target.",
      f: "Regional edge caches hold cacheable objects, including static content; dynamic content that is not cacheable is proxied through to the origin.",
      g: "Regional edge caches are built into CloudFront and used automatically at no extra charge.",
      h: "Local Zones host compute resources near metro areas; they are a different part of AWS infrastructure from CloudFront's Regional edge caches.",
      i: "Correct. CloudFront has a small number of Regional edge caches, each with more capacity than an edge location, so objects stay cached longer.",
    },
    referenceUrl: "https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/HowCloudFrontWorks.html",
    referenceLabel: "How CloudFront delivers content",
    consoleUrl: "https://console.aws.amazon.com/cloudfront/v4/home#/distributions",
    consoleLabel: "CloudFront > Distributions",
    diagram: "flowchart LR\n  Viewer[Viewer] --> Edge[Edge location]\n  Edge -->|cache miss| REC[Regional edge cache]\n  REC -->|cache miss| Origin[Origin: S3 or ALB]\n  Origin --> REC --> Edge --> Viewer",
