    consoleLabel: "AWS Organizations > Accounts",
    diagram: "flowchart LR\n  E[Envision\nopportunities] --> A[Align\ngaps and buy-in]\n  A --> L[Launch\npilots]\n  L --> S[Scale\nexpand pilots, realize value]\n  S -.->|iterate| E",
