    id: "cc164",
    domain: "cloud-concepts",
    text: "An architect notes that AWS has announced a new Region opening next year and wants to plan a highly available deployment there from day one. Based on how AWS builds its global infrastructure, what can the architect assume about the new Region?",
    options: [
      { id: "a", text: "New Regions launch with a single Availability Zone and add more only when demand grows" },
      { id: "b", text: "New Regions share Availability Zones with the nearest existing Region until they are fully built" },
      { id: "c", text: "New Regions launch with exactly two Availability Zones" },
      { id: "d", text: "New Regions launch with a minimum of three Availability Zones, each physically separated with independent power, cooling, and networking" },
      { id: "e", text: "New Regions are Local Zones until they are promoted to full Regions" },
      { id: "f", text: "New Regions contain a single large data center with redundant hardware inside it" },
      { id: "g", text: "New Regions are enabled automatically in every existing AWS account" },
      { id: "h", text: "New Regions initially offer only edge services such as CloudFront and Route 53" },
      { id: "i", text: "Its Availability Zones will be interconnected with redundant, low-latency private fiber" },
    ],
    correctOptionIds: ["d", "i"],
    answerType: "single",
    explanation: "AWS designs every Region to be fully isolated and, for Regions launched in recent years, to consist of a minimum of three Availability Zones. Each AZ is one or more discrete data centers with independent power, cooling, and physical security, separated by a meaningful distance and connected by low-latency links. This lets customers design for Multi-AZ high availability in any new Region from the start. Newer Regions are typically opt-in, so an account administrator must enable them.",
    optionRationale: {
      a: "AWS does not launch single-AZ Regions; multi-AZ resilience is part of the Region design.",
      b: "Regions never share Availability Zones; each Region is fully isolated.",
      c: "The AWS minimum for Regions is three AZs, not two.",
      d: "Correct. AWS builds new Regions with at least three isolated Availability Zones.",
      e: "Local Zones are extensions of a parent Region, not a stage before becoming a Region.",
      f: "A single data center, however redundant, would not provide the fault isolation of separate AZs.",
      g: "Regions launched since 2019 are disabled by default and must be opted into.",
      h: "New Regions launch with a broad set of core services, not only edge services.",
      i: "Correct. AWS links the AZs of every Region with redundant, low-latency metro fiber, which is what makes synchronous Multi-AZ designs practical from launch.",
    },
    referenceUrl: "https://aws.amazon.com/about-aws/global-infrastructure/regions_az/",
    referenceLabel: "Regions and Availability Zones - AWS Global Infrastructure",
