    explanation: "The AWS Well-Architected Tool lets you save a milestone, which records the state of a workload review, including its answers and identified risks, at a point in time. Teams typically save a milestone after the initial review and again after each improvement cycle so they can measure how many high- and medium-risk issues have been resolved. Milestones are stored in the tool itself and can be compared side by side.",
