    correctOptionIds: ["b", "i"],
    answerType: "single",
    explanation: "The approach reflects two Well-Architected general design principles: automate with architectural experimentation in mind, because templates make it cheap to build several designs in parallel and tear down the losers, and drive architectures using data, because the choice comes from measured results rather than debate. This turns architecture decisions into cheap experiments rather than expensive bets.",
