    id: "cc177",
    domain: "cloud-concepts",
    text: "A photo-sharing application runs on several EC2 instances behind a load balancer. Uploaded images are saved to the local EBS volume of whichever instance received the upload. Users complain that their photos sometimes appear missing, because later requests are served by a different instance. Which change BEST follows cloud architecture best practices?",
    options: [
      { id: "a", text: "Increase the size of each instance's EBS volume so more photos can be stored locally" },
      { id: "b", text: "Reduce the fleet to one large instance so all uploads land on the same disk" },
      { id: "c", text: "Copy the uploads between instances every hour with a cron job" },
      { id: "d", text: "Store uploaded images in Amazon S3 so every instance reads and writes the same durable, shared object store" },
      { id: "e", text: "Enable sticky sessions on the load balancer so users always return to the instance that holds their photos" },
      { id: "f", text: "Attach the same EBS volume to all instances in every Availability Zone" },
      { id: "g", text: "Take hourly EBS snapshots and restore them onto the other instances" },
      { id: "h", text: "Configure the load balancer to broadcast each upload to all instances" },
      { id: "i", text: "Save uploaded images to an Amazon EFS file system that every instance mounts as shared storage" },
    ],
    correctOptionIds: ["d", "i"],
    answerType: "single",
    explanation: "Decoupling storage from compute is a core cloud design pattern: application servers should be interchangeable and stateless, with shared data kept in a durable service such as Amazon S3 (for objects) or Amazon EFS (for shared file systems). Moving uploads to S3 means any instance can serve any request, instances can be added or replaced freely, and the data is stored with high durability instead of on a single instance's disk.",
    optionRationale: {
      a: "Larger local disks do not make data visible to other instances.",
      b: "A single instance is a single point of failure and removes elasticity.",
      c: "Periodic copying is fragile, delays visibility, and multiplies storage cost.",
      d: "Correct. S3 provides a shared, durable store so compute becomes stateless and replaceable.",
      e: "Sticky sessions do not help when the instance is replaced, and the data is still at risk on one disk.",
      f: "A standard EBS volume is zonal and normally attaches to one instance; multi-attach is limited to specific volume types and cannot cross AZs.",
      g: "Snapshots are for backup, not for keeping a fleet in sync in near real time.",
      h: "Load balancers forward each request to one target; they do not replicate uploads.",
      i: "Correct. EFS is a durable file system shared across instances and Availability Zones, so any instance can serve any photo and compute stays stateless.",
    },
    referenceUrl: "https://docs.aws.amazon.com/AmazonS3/latest/userguide/Welcome.html",
    referenceLabel: "What is Amazon S3?",
