    text: "An online store's product page calls a recommendations service to show 'customers also bought' items. When the recommendations service is down, the entire product page returns an error and customers cannot buy anything. Which resilience practice should the architect apply?",
    options: [
      { id: "a", text: "Make the recommendations call synchronous with a longer timeout so it eventually succeeds" },
      { id: "b", text: "Design the product page to degrade gracefully by rendering without recommendations, or with a cached default list, when the dependency fails" },
      { id: "c", text: "Move the recommendations service onto the same EC2 instance as the product page" },
      { id: "d", text: "Return a maintenance page for the whole site whenever any dependency is unhealthy" },
      { id: "e", text: "Disable monitoring on the recommendations service so its failures are not reported" },
      { id: "f", text: "Require customers to log in again when the recommendations service recovers" },
      { id: "g", text: "Increase the product page's instance size so it can wait longer for the dependency" },
      { id: "h", text: "Stop showing recommendations permanently to remove the dependency" },
      { id: "i", text: "Wrap the recommendations call in a circuit breaker so the page skips it and still loads while the service is failing" },
    ],
    correctOptionIds: ["b", "i"],
    answerType: "single",
    explanation: "Graceful degradation keeps a workload's core function working when a non-critical dependency fails. The Reliability pillar recommends treating such dependencies as soft, using short timeouts or a circuit breaker to stop calling a failing service, and rendering the page with a cached or empty fallback so customers can still buy.",
    optionRationale: {
      a: "Longer synchronous waits make the page slower and still fail when the dependency is down.",
      b: "Correct. Treat the dependency as optional and fall back so the core purchase flow keeps working.",
      c: "Co-locating services does not stop the service from failing and creates a larger single point of failure.",
      d: "A site-wide maintenance page is the opposite of graceful degradation.",
      e: "Hiding failures removes visibility; it does not improve resilience.",
      f: "Re-authentication is unrelated to dependency failure handling.",
      g: "Instance size does not change how a failed dependency behaves.",
      h: "Removing the feature sacrifices business value; the goal is to tolerate its failure, not delete it.",
      i: "Correct. A circuit breaker stops calling the failing dependency and lets the page render without it, so purchases keep working.",
    },
    referenceUrl: "https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/rel_mitigate_interaction_failure_graceful_degradation.html",
    referenceLabel: "Implement graceful degradation to transform applicable hard dependencies into soft dependencies - Reliability Pillar",
    consoleUrl: "https://ap-southeast-1.console.aws.amazon.com/cloudwatch/home?region=ap-southeast-1#alarmsV2:",
    consoleLabel: "CloudWatch > Alarms",
    diagram: "flowchart LR\n  P[Product page] -->|short timeout| R[Recommendations service]\n  R -- healthy --> Full[Page with recommendations]\n  R -- failed --> Fallback[Page with cached default list\ncheckout still works]",
    cliExample: {
      description: "Create an alarm that fires when the recommendations service's error rate rises, so the fallback path can be watched",
      command: "aws cloudwatch put-metric-alarm --region ap-southeast-1 --alarm-name recommendations-5xx --namespace AWS/ApplicationELB --metric-name HTTPCode_Target_5XX_Count --dimensions Name=LoadBalancer,Value=app/recs-alb/50dc6c495c0c9188 --statistic Sum --period 60 --evaluation-periods 3 --threshold 50 --comparison-operator GreaterThanThreshold --alarm-actions arn:aws:sns:ap-southeast-1:123456789012:ops-alerts",
      sampleOutput: "",
    },
