    diagram: "flowchart LR\n  P1[Partner A\n50,000 req/s] --> APIGW[API Gateway\nusage plan: 1,000 req/s per key]\n  P2[Partner B\n200 req/s] --> APIGW\n  APIGW -->|429 Too Many Requests| P1\n  APIGW -->|allowed| BE[Backend service]",
