    id: "cc186",
    domain: "cloud-concepts",
    text: "A company currently runs its application in a single AWS Region with resources spread across three Availability Zones. Leadership asks in which situations it would be worth the additional cost and complexity of deploying the application in a second Region. Which TWO are valid reasons to adopt a multi-Region architecture? (Select TWO.)",
    options: [
      { id: "a", text: "To protect the application against the unlikely failure of an entire Region, meeting a disaster recovery objective that a single Region cannot satisfy" },
      { id: "b", text: "To serve users in a distant geography with lower latency by running the application closer to them" },
      { id: "c", text: "To protect the application against the failure of a single Availability Zone" },
      { id: "d", text: "Because AWS requires every production workload to run in at least two Regions" },
      { id: "e", text: "To reduce the total AWS bill, since a second Region halves the cost of the first" },
      { id: "f", text: "To obtain a higher EBS volume size limit, which is doubled when two Regions are used" },
      { id: "g", text: "Because IAM users must be created separately in every Region where an application runs" },
      { id: "h", text: "To avoid having to configure Auto Scaling in the primary Region" },
      { id: "i", text: "To keep certain customers' data within a required jurisdiction to comply with data residency rules" },
      { id: "j", text: "To meet a regulation that requires the recovery site to be in a separate geographic area from the primary site" },
    ],
    correctOptionIds: ["a", "b", "i", "j"],
    answerType: "multi",
    explanation: "A multi-AZ deployment already protects against data center and Availability Zone failures within a Region. A second Region is justified by requirements one Region cannot meet, such as surviving a full Regional disruption or a regulatory demand for a geographically separate recovery site, serving distant users with lower latency, or keeping data in a specific jurisdiction, and because it adds cost and complexity it should be a deliberate decision.",
    optionRationale: {
      a: "Correct. Regional-level disaster recovery is a primary reason for multi-Region designs.",
      b: "Correct. Placing the application near distant users reduces latency.",
      c: "AZ failures are already handled by the existing multi-AZ deployment.",
      d: "AWS imposes no such requirement.",
      e: "A second Region adds cost; it does not reduce the first Region's bill.",
      f: "Service limits are not increased by using more Regions.",
      g: "IAM is a global service; users are not created per Region.",
      h: "Auto Scaling is still needed in each Region.",
      i: "Correct. Data residency requirements can only be met by running in a Region located in the required jurisdiction.",
      j: "Correct. Availability Zones sit within one geographic area, so a rule demanding a geographically separate recovery site calls for a second Region.",
    },
    referenceUrl: "https://docs.aws.amazon.com/prescriptive-guidance/latest/aws-multi-region-fundamentals/",
    referenceLabel: "AWS Multi-Region Fundamentals",
    consoleUrl: "https://ap-northeast-2.console.aws.amazon.com/ec2/home?region=ap-northeast-2#Home:",
    consoleLabel: "EC2 > Dashboard (Region selector)",
    diagram: "flowchart LR\n  U1[Users in Asia] --> R1[ap-northeast-2\nmulti-AZ]\n  U2[Users in Europe] --> R2[eu-west-1\nmulti-AZ]\n  R1 <-->|data replication| R2\n  R1 -. Regional failure .-> R2",
    cliExample: {
      description: "List the Regions currently enabled for the account when planning a second Region",
      command: "aws ec2 describe-regions --region ap-northeast-2 --query \"Regions[?RegionName=='ap-northeast-2' || RegionName=='eu-west-1'].{Region:RegionName,Endpoint:Endpoint,OptIn:OptInStatus}\"",
      sampleOutput: "[\n  {\n    \"Region\": \"ap-northeast-2\",\n    \"Endpoint\": \"ec2.ap-northeast-2.amazonaws.com\",\n    \"OptIn\": \"opt-in-not-required\"\n  },\n  {\n    \"Region\": \"eu-west-1\",\n    \"Endpoint\": \"ec2.eu-west-1.amazonaws.com\",\n    \"OptIn\": \"opt-in-not-required\"\n  }\n]",
    },
