      g: "Trusted Advisor provides recommendations across cost, security, and performance.",
      h: "CodeArtifact stores software packages such as npm or Maven artifacts.",
      i: "Correct. The toolkit embeds the Infrastructure Composer visual canvas in the IDE, generating CloudFormation or SAM templates as you drag in services.",
