    domain: "cloud-concepts",
    text: "A company assessing its readiness for cloud adoption with the AWS Cloud Adoption Framework (AWS CAF) discovers that no one is accountable for cloud cost, security policies are informal, and there is no plan to reskill staff. Which AWS CAF perspective addresses the plan to reskill staff and prepare the workforce for a cloud operating model?",
    options: [
      { id: "a", text: "People" },
      { id: "b", text: "Platform" },
      { id: "c", text: "Operations" },
      { id: "d", text: "Business" },
      { id: "e", text: "Security" },
      { id: "f", text: "Governance" },
      { id: "g", text: "Reliability" },
      { id: "h", text: "Performance Efficiency" },
      { id: "i", text: "People: culture and change" },
    ],
    correctOptionIds: ["a", "i"],
    answerType: "single",
    explanation: "The AWS CAF has six perspectives: Business, People, Governance, Platform, Security, and Operations. The People perspective serves as a bridge between technology and business, focusing on culture, organizational structure, leadership, and workforce skills so that the organization can evolve toward a cloud-ready operating model. Governance covers cost management and risk, Security covers policy and controls, and Platform covers the technical foundations.",
    optionRationale: {
      a: "Correct. The People perspective addresses culture, organization, leadership, and workforce reskilling.",
      b: "Platform covers building the cloud environment: architecture, provisioning, and data engineering.",
      c: "Operations focuses on running workloads reliably: observability, incident management, and change.",
      d: "Business focuses on strategy, portfolio, and ensuring cloud investments accelerate business outcomes.",
      e: "Security covers achieving confidentiality, integrity, and availability of workloads.",
      f: "Governance orchestrates cloud initiatives, benefits, risk, and cloud financial management, so it would address the cost-accountability gap rather than reskilling.",
      g: "Reliability is a Well-Architected pillar, not a CAF perspective.",
      h: "Performance Efficiency is a Well-Architected pillar, not a CAF perspective.",
      i: "Correct. AWS subtitles the People perspective 'culture and change', covering leadership, organization design, and workforce skills.",
    },
    referenceUrl: "https://docs.aws.amazon.com/whitepapers/latest/overview-aws-cloud-adoption-framework/people-perspective.html",
    referenceLabel: "AWS CAF: People perspective",
    consoleUrl: "https://console.aws.amazon.com/wellarchitected/home#/workloads",
    consoleLabel: "Well-Architected Tool > Workloads",
    diagram: "flowchart LR\n  CAF[AWS CAF] --> B[Business]\n  CAF --> P[People: culture, skills, leadership]\n  CAF --> G[Governance]\n  CAF --> Pl[Platform]\n  CAF --> S[Security]\n  CAF --> O[Operations]",
