      g: "Prepare for failure is an Operational Excellence idea (anticipate failure).",
      h: "Understand your impact is a Sustainability pillar principle.",
      i: "Correct. This is how the Performance Efficiency pillar describes democratizing advanced technologies: consume complex technology as a service instead of learning to run it.",
