    answerType: "multi",
    explanation: "Edge locations, also called points of presence, are sites in major cities that host services which need to be close to end users: Amazon CloudFront caches and serves content, Amazon Route 53 answers DNS queries, and AWS Global Accelerator, AWS Shield, and AWS WAF also operate at the edge. Compute, database, and storage services such as RDS, EBS, Redshift, EFS, Batch, and EMR run inside Availability Zones within a Region.",
