    domain: "cloud-concepts",
    text: "A company has several Java web applications running on on-premises virtual machines. It wants to move them to Amazon ECS as containers without re-architecting them, and it needs a tool that analyzes the application source code, generates Dockerfiles and container images, and produces the deployment infrastructure code. Which AWS tool and migration strategy fit?",
