    answerType: "single",
    explanation: "AWS Transform's source code containerization analyzes application code, generates Dockerfiles, builds and tests container images, publishes them to Amazon ECR, and generates infrastructure code to deploy them to Amazon ECS or Amazon EKS. AWS points customers to it instead of AWS App2Container, which closed to new customers on November 7, 2025. Moving from virtual machines to containers while keeping the application architecture intact is the replatform ('lift, tinker, and shift') strategy. AWS Transform MGN (formerly Application Migration Service) rehosts whole servers, and DMS handles databases.",
