    text: "A 10-person startup handles sensitive customer data but cannot afford 24/7 guarded facilities, hardware disposal procedures, or annual third-party audits such as SOC 2 and ISO 27001 for its own infrastructure. A consultant explains that running on AWS addresses much of this. Which cloud value proposition does this illustrate?",
