    explanation: "One of the core benefits of the cloud is that AWS invests heavily in security and compliance, and every customer inherits the physical, environmental, and infrastructure controls that AWS operates and has audited under programs such as SOC, ISO, and PCI DSS. Customers can obtain the corresponding audit reports through AWS Artifact to support their own audits. Under the shared responsibility model, the customer still secures its applications, data, and identities.",
