    diagram: "flowchart LR\n  AWS[AWS infrastructure controls: physical, SOC, ISO, PCI] --> Inherit[Inherited by every customer]\n  Inherit --> Startup[Startup focuses on app, data, IAM]\n  Startup --> Audit[Own audit uses AWS Artifact reports]",
