      sampleOutput: "[\n  {\n    \"Zone\": \"us-west-2-lax-1a\",\n    \"Group\": \"us-west-2-lax-1\",\n    \"State\": \"available\",\n    \"OptIn\": \"opted-in\"\n  },\n  {\n    \"Zone\": \"us-west-2-las-1a\",\n    \"Group\": \"us-west-2-las-1\",\n    \"State\": \"available\",\n    \"OptIn\": \"not-opted-in\"\n  }\n]",
