    text: "A company is building an augmented reality mobile application whose users connect over a telecom carrier's 5G network. The application must keep round-trip latency to its backend as low as possible by avoiding hops across the public internet to a distant AWS Region. Which AWS offering embeds AWS compute and storage directly inside the carrier's network?",
